const MAX_ITEMS: usize = 32;
#[derive(Clone,Copy)] struct Node { data:u16, idx:i32, next:i32 }
fn crc_byte(mut value:u8,mut crc:u16)->u16{for _ in 0..8{let mix=(value&1)^(crc as u8&1);value>>=1;if mix!=0{crc^=0x4002;}crc>>=1;if mix!=0{crc|=0x8000;}else{crc&=0x7fff;}}crc}
fn crc16(value:u16,crc:u16)->u16{crc_byte((value>>8) as u8,crc_byte(value as u8,crc))}
fn compare(a:&mut [Node;MAX_ITEMS+2],x:usize,y:usize,complex:bool,seed:u16)->i32{if complex{if a[x].data&0x80==0{a[x].data=(a[x].data&0xff00)|0x80|((a[x].data^(a[x].data>>8)^seed)&0x7f);}if a[y].data&0x80==0{a[y].data=(a[y].data&0xff00)|0x80|((a[y].data^(a[y].data>>8)^seed)&0x7f);}i32::from(a[x].data&127)-i32::from(a[y].data&127)}else{a[x].data=(a[x].data&0xff00)|((a[x].data>>8)&255);a[y].data=(a[y].data&0xff00)|((a[y].data>>8)&255);a[x].idx-a[y].idx}}
fn sort(a:&mut [Node;MAX_ITEMS+2],mut head:i32,complex:bool,seed:u16)->i32{let mut width=1i32;loop{let(mut p,mut new_head,mut tail,mut merges)=(head,-1,-1,0);while p>=0{merges+=1;let(mut q,mut ps)=(p,0);for _ in 0..width{ps+=1;q=a[q as usize].next;if q<0{break;}}let mut qs=width;while ps>0||(qs>0&&q>=0){let e;if ps==0{e=q;q=a[q as usize].next;qs-=1;}else if qs==0||q<0{e=p;p=a[p as usize].next;ps-=1;}else if compare(a,p as usize,q as usize,complex,seed)<=0{e=p;p=a[p as usize].next;ps-=1;}else{e=q;q=a[q as usize].next;qs-=1;}if tail>=0{a[tail as usize].next=e;}else{new_head=e;}tail=e;}p=q;}a[tail as usize].next=-1;head=new_head;if merges<=1{return head;}width*=2;}}
fn find(a:&[Node;MAX_ITEMS+2],mut head:i32,idx:i32,data:i32)->i32{while head>=0{let n=a[head as usize];if if idx>=0{n.idx==idx}else{n.data&255==data as u16}{return head;}head=n.next;}-1}
fn reverse(a:&mut [Node;MAX_ITEMS+2],head:&mut i32){let(mut prev,mut cur)=(-1,*head);while cur>=0{let next=a[cur as usize].next;a[cur as usize].next=prev;prev=cur;cur=next;}*head=prev;}

#[no_mangle]
pub unsafe extern "C" fn embedded_list_stress(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{
 if input.is_null()||length!=4{return -1;}let v=std::slice::from_raw_parts(input,length);let(n,seed,find_count,mode)=(v[0],v[1],v[2],v[3]);if n<4||n>MAX_ITEMS as i64||seed<1||seed>255||find_count<0||find_count>32||!(mode==-1||mode==1){return -1;}
 let n=n as usize;let tail=(n+1) as i32;let mut a=[Node{data:0,idx:0,next:-1};MAX_ITEMS+2];a[0]=Node{data:0x8080,idx:0,next:1};a[tail as usize]=Node{data:0xffff,idx:0x7fff,next:-1};for i in 0..n{let dat=((((seed as usize^i)&15)<<3)|(i&7)) as u16;a[i+1]=Node{data:(dat<<8)|dat,idx:0,next:(i+2) as i32};}a[n].next=tail;
 let(mut i,mut p)=(1, a[0].next);while p!=tail{let u=p as usize;if i<n/5{a[u].idx=i as i32;i+=1;}else{let pat=i as i64^seed;i+=1;a[u].idx=((((i&7)<<8) as i64|pat)&0x3fff) as i32;}p=a[u].next;}let mut head=sort(&mut a,0,false,seed as u16);
 let(mut info_idx,mut info_data)=(mode as i32,0);let(mut result,mut found,mut missed)=(0u16,0u32,0u32);for k in 0..find_count as i32{info_data=k&255;let got=find(&a,head,info_idx,info_data);reverse(&mut a,&mut head);if got<0{missed+=1;let first=a[head as usize].next;if first>=0{result=result.wrapping_add((a[first as usize].data>>8)&1);}}else{found+=1;let node=a[got as usize];if node.data&1!=0{result=result.wrapping_add((node.data>>9)&1);}let next=node.next;if next>=0{a[got as usize].next=a[next as usize].next;a[next as usize].next=a[head as usize].next;a[head as usize].next=next;}}if info_idx>=0{info_idx+=1;}}
 result=result.wrapping_add((found*4).wrapping_sub(missed) as u16);if mode>0{head=sort(&mut a,head,true,seed as u16);}let at=a[head as usize].next;if at>=0{let rem=a[at as usize].next as usize;let at=at as usize;let temp=a[at].data;a[at].data=a[rem].data;a[rem].data=temp;let temp=a[at].idx;a[at].idx=a[rem].idx;a[rem].idx=temp;a[at].next=a[rem].next;a[rem].next=-1;let mut f=find(&a,head,info_idx,info_data);if f<0{f=a[head as usize].next;}while f>=0{result=crc16(a[head as usize].data,result);f=a[f as usize].next;}let temp=a[rem].data;a[rem].data=a[at].data;a[at].data=temp;let temp=a[rem].idx;a[rem].idx=a[at].idx;a[at].idx=temp;a[rem].next=a[at].next;a[at].next=rem as i32;}
 head=sort(&mut a,head,false,seed as u16);let mut f=a[head as usize].next;while f>=0{result=crc16(a[head as usize].data,result);f=a[f as usize].next;}if output.is_null()||capacity<2{return -2;}*output=result as u8;*output.add(1)=(result>>8) as u8;2
}
